docker compose -f lab/compose.yaml exec -T base psql -U postgres -d busqueda_base -c "WITH q AS (SELECT plainto_tsquery('es_unaccent','helice tripala') q) SELECT n, count(*) FILTER (WHERE description='hélice tripala') AS aciertos FROM generate_series(0,2) n, LATERAL (SELECT description FROM part_catalog, q WHERE description_tsv @@ q.q ORDER BY ts_rank(description_tsv, q.q, CASE n WHEN 0 THEN 0 WHEN 1 THEN 1 ELSE 2 END) DESC, part_number LIMIT 10) t GROUP BY n ORDER BY n"
